mapper.update:
UPDATE MAP_ROLE_MENU

    READ_YN = #{dto.readYn},
    CREATE_YN = #{dto.createYn},
    UPDATE_YN = #{dto.updateYn},
    DELETE_YN = #{dto.deleteYn},
    EXCEL_YN = #{dto.excelYn},
    UPDATED_AT = SYSDATE,
    UPDATED_BY = #{loginUserId}

WHERE ROLE_CODE = #{roleCode}
AND MENU_ID = #{menuId}

mapper.delete:
DELETE FROM MAP_ROLE_MENU
WHERE ROLE_CODE = #{roleCode}
AND MENU_ID = #{menuId}
